"use client";

import { useId, useMemo, useRef, useState, useSyncExternalStore, type ComponentProps, type KeyboardEvent } from "react";

import { IconChevronLeft, IconChevronRight } from "@rhs-ui/icons";
import { DEFAULT_LABELS, describePeriod, endOf, fill, isDay, labelSamples, shift, startOf, todayIn, type PeriodStepperLabels, type PeriodUnit } from "@rhs-ui/application/period-stepper/periods";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export type { PeriodStepperLabels, PeriodUnit } from "@rhs-ui/application/period-stepper/periods";

/** The period that was moved to: its first and last day, as calendar days, and its unit. */
export interface PeriodRange {
  /** The first day, "2026-10-19". */
  start: string;
  /** The last day, "2026-10-25". */
  end: string;
  unit: PeriodUnit;
}

export interface PeriodStepperProps extends Omit<ComponentProps<"div">, "onChange" | "defaultValue" | "children"> {
  /** What a step is: a day, a week, a month or a year. Default "week". */
  unit?: PeriodUnit;
  /** Any day inside the period shown, as "2026-10-21": the stepper shows the period that holds it. A day is a calendar day, never a moment, so it does not shift with a time zone. Controlled: pair it with `onChange`. */
  value?: string;
  /** The day the period is taken from at the start, when you do not control it. Default today. */
  defaultValue?: string;
  /** A different period was moved to, by a button, an arrow key or Today. It receives the period's first day and its range. */
  onChange?: (start: string, range: PeriodRange) => void;
  /** The first day that can be shown, "2026-01-01". The previous button stops at the period that holds it. */
  min?: string;
  /** The last day that can be shown. The next button stops at the period that holds it. */
  max?: string;
  /** The first day of the week: 0 for Sunday, 1 for Monday (the default) up to 6 for Saturday. It also decides how weeks are numbered. */
  weekStart?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  /** The language the label is written in. Default "en-US". */
  locale?: string;
  /** The time zone that decides what today is, so the server and the browser agree. Default "UTC". */
  timeZone?: string;
  /**
   * Pins today ("2026-10-26"), for previews and tests. Leave it out to use the browser's clock, read once the page is
   * live. The period first drawn when you pass no `value` still comes from the clock of whoever renders it, so a page
   * that is cached or built ahead of time must pass `value` or `today` (or render the stepper on the client only).
   */
  today?: string;
  /** Draws the Today button while the period shown is not the current one. Default true. */
  showToday?: boolean;
  /** The words the stepper says, for translation. */
  labels?: PeriodStepperLabels;
}

const subscribeNever = () => () => undefined;

/**
 * The least room a label has, so a short one (a year, a weekday) still gives the buttons some air. What keeps the
 * buttons from moving as the label changes is not this, it is the sizer in the label: the widest text the unit and the
 * language can show, drawn invisibly, so the room is the longest label's whatever its font or its language.
 */
const LABEL_WIDTH: Record<PeriodUnit, string> = {
  day: "min-w-32",
  week: "min-w-32",
  month: "min-w-32",
  year: "min-w-20",
};

/**
 * A small control for moving through time in a report or a calendar: a
 * previous button, the period in words ("Week 43, 19 to 25 Oct 2026") and a
 * next button, with a Today button that appears only while the period shown is
 * not the current one. It steps by a day, a week, a month or a year, the
 * buttons switch off at `min` and `max`, and the label is a polite live region
 * that is also a stop of its own: with focus on it the left and right arrow
 * keys step, so a screen reader hears each new period. Days are calendar days
 * written as 2026-10-26, so nothing shifts with a time zone; the label, the
 * first day of the week and the week numbers follow the locale. The control
 * keeps the width of the widest label its unit can show in that language, so
 * the Next button does not move under the pointer while you step through it.
 */
export function PeriodStepper({
  unit = "week",
  value,
  defaultValue,
  onChange,
  min,
  max,
  weekStart = 1,
  locale = "en-US",
  timeZone = "UTC",
  today: pinnedToday,
  showToday = true,
  labels,
  className,
  ...props
}: PeriodStepperProps) {
  const text: Required<PeriodStepperLabels> = { ...DEFAULT_LABELS, ...labels, units: { ...DEFAULT_LABELS.units, ...labels?.units } };
  const hintId = useId();
  const label = useRef<HTMLDivElement>(null);
  const [own, setOwn] = useState(() => (isDay(defaultValue) ? defaultValue : (pinnedToday ?? todayIn(timeZone))));
  // Today is known only in the browser: the server draws no Today button, so it cannot mismatch. A pinned day is known everywhere.
  const today = useSyncExternalStore(
    subscribeNever,
    () => pinnedToday ?? todayIn(timeZone),
    () => pinnedToday ?? null,
  );

  const anchor = isDay(value) ? value : own;
  // The period that holds the day; one that lies wholly outside the limits gives way to the one that holds the limit.
  let start = startOf(unit, anchor, weekStart);
  if (isDay(min) && endOf(unit, start) < min) start = startOf(unit, min, weekStart);
  if (isDay(max) && start > max) start = startOf(unit, max, weekStart);

  const lowest = isDay(min) ? min : null;
  const highest = isDay(max) ? max : null;
  const before = (from: string) => lowest !== null && endOf(unit, shift(unit, from, -1)) < lowest;
  const after = (from: string) => highest !== null && shift(unit, from, 1) > highest;
  const previousBlocked = before(start);
  const nextBlocked = after(start);

  const current = today === null ? null : startOf(unit, today, weekStart);
  const outside = current !== null && ((lowest !== null && endOf(unit, current) < lowest) || (highest !== null && current > highest));
  const canJump = showToday && current !== null && current !== start && !outside;

  function go(next: string, focusLabel: boolean) {
    if (value === undefined) setOwn(next);
    onChange?.(next, { start: next, end: endOf(unit, next), unit });
    // The button that was pressed may be off now, or gone: the label is where focus waits.
    if (focusLabel) label.current?.focus();
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.altKey || event.ctrlKey || event.metaKey || (event.key !== "ArrowLeft" && event.key !== "ArrowRight")) return;
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl";
    const forward = (event.key === "ArrowRight") !== rtl;
    event.preventDefault();
    if (forward ? nextBlocked : previousBlocked) return;
    go(shift(unit, start, forward ? 1 : -1), false);
  }

  const period = describePeriod(unit, start, { locale, weekStart, text });
  const word = text.units[unit] ?? DEFAULT_LABELS.units[unit];
  // The widest label this unit and language can show: it holds the room, so the buttons stay put while the label changes.
  const samples = useMemo(() => labelSamples(unit, { locale, weekStart, week: text.week, to: text.to }), [unit, locale, weekStart, text.week, text.to]);

  return (
    <div data-slot="period-stepper" data-unit={unit} className={cn("flex flex-wrap items-center gap-2", className)} {...props}>
      <div role="group" aria-label={text.group} className="inline-flex h-10 max-w-full min-w-0 items-stretch rounded-lg border border-border bg-background shadow-xs">
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label={fill(text.previous, { unit: word })}
          disabled={previousBlocked}
          onClick={() => go(shift(unit, start, -1), before(shift(unit, start, -1)))}
          className="h-full w-9 shrink-0 rounded-none rounded-s-[7px] text-muted-foreground hover:text-foreground focus-visible:ring-inset"
        >
          <IconChevronLeft className="rtl:rotate-180" />
        </Button>
        {/* Two things in one cell of a grid: the label, and under it the sizer, which is never seen. The cell is as wide as the wider of the two, and it clips, so in a container too narrow for it the label shrinks and its lines end in an ellipsis instead of widening the page. */}
        <div className="grid min-w-0 flex-1 grid-cols-[minmax(0,1fr)] overflow-hidden border-x border-border">
          <span
            aria-hidden="true"
            data-slot="period-stepper-sizer"
            suppressHydrationWarning
            className={cn("invisible col-start-1 row-start-1 flex flex-col items-center justify-center px-2 text-center whitespace-nowrap tabular-nums", LABEL_WIDTH[unit])}
          >
            <span suppressHydrationWarning className="grid text-sm leading-5 font-medium">
              {samples.primary.map((sample, index) => (
                <span key={index} suppressHydrationWarning className="col-start-1 row-start-1 first-letter:uppercase">
                  {sample}
                </span>
              ))}
            </span>
            {samples.secondary.length ? (
              <span suppressHydrationWarning className="grid text-xs leading-4">
                {samples.secondary.map((sample, index) => (
                  <span key={index} suppressHydrationWarning className="col-start-1 row-start-1">
                    {sample}
                  </span>
                ))}
              </span>
            ) : null}
          </span>
          <div
            ref={label}
            role="status"
            aria-live="polite"
            aria-atomic="true"
            aria-describedby={hintId}
            aria-keyshortcuts="ArrowLeft ArrowRight"
            tabIndex={0}
            onKeyDown={onKeyDown}
            suppressHydrationWarning
            className="col-start-1 row-start-1 flex min-w-0 flex-col items-center justify-center px-2 text-center tabular-nums outline-none focus-visible:ring-[3px] focus-visible:ring-ring/40 focus-visible:ring-inset"
          >
            <span suppressHydrationWarning className="max-w-full truncate text-sm leading-5 font-medium text-foreground first-letter:uppercase">
              {period.primary}
            </span>
            {period.secondary ? (
              <>
                <span className="sr-only">, </span>
                <span suppressHydrationWarning className="max-w-full truncate text-xs leading-4 text-muted-foreground">
                  {period.secondary}
                </span>
              </>
            ) : null}
          </div>
        </div>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label={fill(text.next, { unit: word })}
          disabled={nextBlocked}
          onClick={() => go(shift(unit, start, 1), after(shift(unit, start, 1)))}
          className="h-full w-9 shrink-0 rounded-none rounded-e-[7px] text-muted-foreground hover:text-foreground focus-visible:ring-inset"
        >
          <IconChevronRight className="rtl:rotate-180" />
        </Button>
      </div>
      {canJump && current !== null ? (
        <Button type="button" variant="outline" className="h-10 px-3" onClick={() => go(current, true)}>
          {text.today}
        </Button>
      ) : null}
      <span id={hintId} className="sr-only">
        {text.hint}
      </span>
    </div>
  );
}

/**
 * The calendar behind PeriodStepper, as plain functions: they hold no state and
 * call no hook, so a Server Component can use them too. A day is the string
 * "2026-10-26": a day on the calendar, not a moment, so it never shifts with a
 * time zone. All the arithmetic runs in UTC for that reason, and only `todayIn`
 * looks at a clock. Every function that writes a date takes the locale.
 */

export type PeriodUnit = "day" | "week" | "month" | "year";

/** The words the stepper says, for translation. `{unit}` and `{number}` are filled in. */
export interface PeriodStepperLabels {
  /** The name of the group of controls. Default "Change period". */
  group?: string;
  /** The name of the button that goes back; `{unit}` is the word for the unit. Default "Previous {unit}". */
  previous?: string;
  /** The name of the button that goes forward. Default "Next {unit}". */
  next?: string;
  /** The button that brings the current period back. Default "Today". */
  today?: string;
  /** The label of a week; `{number}`. Default "Week {number}". */
  week?: string;
  /** Joins the two ends of a range: "19 to 25 Oct 2026". Default "to". */
  to?: string;
  /** Said to a screen reader when the label has focus. Default "Use the left and right arrow keys to change the period." */
  hint?: string;
  /** The words for the units, as they go into `previous` and `next`. Default day, week, month and year. */
  units?: Partial<Record<PeriodUnit, string>>;
}

export const DEFAULT_LABELS = {
  group: "Change period",
  previous: "Previous {unit}",
  next: "Next {unit}",
  today: "Today",
  week: "Week {number}",
  to: "to",
  hint: "Use the left and right arrow keys to change the period.",
  units: { day: "day", week: "week", month: "month", year: "year" },
} satisfies Required<PeriodStepperLabels>;

/** Fills `{name}` marks in a sentence. A mark with no value stays as it is. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (mark, key: string) => (key in values ? String(values[key]) : mark));
}

const DAY_MS = 86_400_000;
const PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Whether the text is a real calendar day, such as "2026-10-26". "2026-02-30" is not. */
export function isDay(value: string | null | undefined): value is string {
  const match = value ? PATTERN.exec(value) : null;
  if (!match) return false;
  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function toNumber(day: string): number {
  const match = PATTERN.exec(day);
  return Date.UTC(Number(match?.[1]), Number(match?.[2]) - 1, Number(match?.[3])) / DAY_MS;
}

const fromNumber = (count: number): string => new Date(count * DAY_MS).toISOString().slice(0, 10);

/** The day `count` days after (or, when negative, before) `day`. */
export function addDays(day: string, count: number): string {
  return fromNumber(toNumber(day) + count);
}

/** 0 for Sunday up to 6 for Saturday. */
export function weekdayOf(day: string): number {
  return new Date(toNumber(day) * DAY_MS).getUTCDay();
}

/** The first day of the week `day` falls in, where `weekStart` is 0 for Sunday and 1 for Monday. */
export function startOfWeek(day: string, weekStart: number): string {
  return addDays(day, -((weekdayOf(day) - weekStart + 7) % 7));
}

/** Today's date in the time zone, so the server and the browser agree. An unknown zone falls back to UTC instead of taking the page down. */
export function todayIn(timeZone: string): string {
  const parts = (zone: string) => new Intl.DateTimeFormat("en-US", { timeZone: zone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(Date.now());
  let found: Intl.DateTimeFormatPart[];
  try {
    found = parts(timeZone);
  } catch {
    found = parts("UTC");
  }
  const part = (type: string) => found.find((entry) => entry.type === type)?.value ?? "";
  return `${part("year")}-${part("month")}-${part("day")}`;
}

/** The first day of the period that holds `day`. */
export function startOf(unit: PeriodUnit, day: string, weekStart: number): string {
  switch (unit) {
    case "day":
      return day;
    case "week":
      return startOfWeek(day, weekStart);
    case "month":
      return `${day.slice(0, 7)}-01`;
    case "year":
      return `${day.slice(0, 4)}-01-01`;
  }
}

/** The last day of the period that begins on `start` (a day that is the start of its period). */
export function endOf(unit: PeriodUnit, start: string): string {
  switch (unit) {
    case "day":
      return start;
    case "week":
      return addDays(start, 6);
    case "month":
      // Day 0 of the next month is the last day of this one.
      return fromNumber(Date.UTC(Number(start.slice(0, 4)), Number(start.slice(5, 7)), 0) / DAY_MS);
    case "year":
      return `${start.slice(0, 4)}-12-31`;
  }
}

/** The start of the period `count` periods after (or before, when negative) the one that begins on `start`. */
export function shift(unit: PeriodUnit, start: string, count: number): string {
  switch (unit) {
    case "day":
      return addDays(start, count);
    case "week":
      return addDays(start, count * 7);
    case "month":
      return fromNumber(Date.UTC(Number(start.slice(0, 4)), Number(start.slice(5, 7)) - 1 + count, 1) / DAY_MS);
    case "year":
      return `${String(Number(start.slice(0, 4)) + count).padStart(4, "0")}-01-01`;
  }
}

/**
 * The number of the week the day falls in. With Monday as the first day it is
 * the ISO week: week 1 holds the first Thursday of the year, so a week at the
 * turn of the year can be week 52 or 53 of the old one. With any other first
 * day it is the common calendar count: week 1 is the one that holds 1 January.
 */
export function weekNumber(day: string, weekStart: number): number {
  const first = startOfWeek(day, weekStart);
  if (weekStart === 1) {
    const thursday = toNumber(first) + 3;
    const year = new Date(thursday * DAY_MS).getUTCFullYear();
    const januaryFirst = Date.UTC(year, 0, 1) / DAY_MS;
    return Math.floor((thursday - januaryFirst) / 7) + 1;
  }
  const year = new Date((toNumber(first) + 6) * DAY_MS).getUTCFullYear();
  const weekOne = toNumber(startOfWeek(`${year}-01-01`, weekStart));
  return Math.floor((toNumber(first) - weekOne) / 7) + 1;
}

/** Noon, so no zone can tip the day over. */
const at = (day: string): number => toNumber(day) * DAY_MS + DAY_MS / 2;

/** A day written in the reader's language. An unknown locale falls back to English instead of throwing. */
export function formatDay(day: string, locale: string, options: Intl.DateTimeFormatOptions): string {
  try {
    return new Intl.DateTimeFormat(locale, { ...options, timeZone: "UTC" }).format(at(day));
  } catch {
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(at(day));
  }
}

/**
 * Two days as one range, written the way the locale writes a range, with the
 * dash it would use replaced by a word: "19 to 25 Oct 2026". The locale also
 * decides what is said once ("Oct 2026") and what twice.
 */
export function formatRange(from: string, to: string, locale: string, joiner: string): string {
  const options: Intl.DateTimeFormatOptions = { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" };
  const run = (zone: string) => {
    const formatter = new Intl.DateTimeFormat(zone, options);
    const parts = formatter.formatRangeToParts(at(from), at(to));
    const firstEnd = parts.findIndex((part) => part.source === "endRange");
    const lastStart = parts.reduce((found, part, index) => (part.source === "startRange" ? index : found), -1);
    if (firstEnd < 0 || lastStart < 0 || lastStart > firstEnd) return formatter.formatRange(at(from), at(to));
    // What sits between the last piece of the start and the first piece of the end is the dash.
    return [...parts.slice(0, lastStart + 1), { value: ` ${joiner} ` }, ...parts.slice(firstEnd)].map((part) => part.value).join("");
  };
  try {
    return run(locale);
  } catch {
    return run("en-US");
  }
}

/** A period as it is written: the lead, the part after it when there is one, and the whole as a screen reader hears it. */
export interface PeriodText {
  primary: string;
  secondary?: string;
  full: string;
}

/** How a day is written under its weekday: "26 Oct 2026". */
const DAY_DATE: Intl.DateTimeFormatOptions = { day: "numeric", month: "short", year: "numeric" };

/** What the label of a period says: "Week 43" over "19 to 25 Oct 2026", "October 2026", "2026", or the weekday "Monday" over its date "26 Oct 2026". */
export function describePeriod(unit: PeriodUnit, start: string, options: { locale: string; weekStart: number; text: Required<PeriodStepperLabels> }): PeriodText {
  const { locale, weekStart, text } = options;
  switch (unit) {
    case "day": {
      // Two lines like a week, so a day is not the one unit that needs a label twice as wide as the others.
      const full = formatDay(start, locale, { weekday: "long", ...DAY_DATE });
      return { primary: formatDay(start, locale, { weekday: "long" }), secondary: formatDay(start, locale, DAY_DATE), full };
    }
    case "week": {
      const primary = fill(text.week, { number: new Intl.NumberFormat(locale).format(weekNumber(start, weekStart)) });
      const secondary = formatRange(start, endOf("week", start), locale, text.to);
      return { primary, secondary, full: `${primary}, ${secondary}` };
    }
    case "month": {
      const full = formatDay(start, locale, { month: "long", year: "numeric" });
      return { primary: full, full };
    }
    case "year": {
      const full = formatDay(start, locale, { year: "numeric" });
      return { primary: full, full };
    }
  }
}

const pad = (value: number): string => String(value).padStart(2, "0");

/**
 * The widest text each line of a unit's label can hold, written in the
 * language of the label, so that the label can keep room for it: drawn
 * invisibly in the label's own box it holds the control at one width while it
 * steps, and the buttons stay under the pointer. The widest week range crosses
 * New Year (the year is said twice) and the weeks that do are found in seven
 * years in a row, whatever day the week starts on; the widest month is one of
 * twelve and the widest weekday one of seven. They never depend on the period
 * shown, or the width would jump at the turn of a year.
 */
export function labelSamples(unit: PeriodUnit, options: { locale: string; weekStart: number; week: string; to: string }): { primary: string[]; secondary: string[] } {
  const { locale, weekStart, week, to } = options;
  switch (unit) {
    case "day":
      return {
        primary: Array.from({ length: 7 }, (_, index) => formatDay(addDays("2026-10-26", index), locale, { weekday: "long" })),
        secondary: Array.from({ length: 12 }, (_, month) => formatDay(`2026-${pad(month + 1)}-28`, locale, DAY_DATE)),
      };
    case "week":
      return {
        primary: [fill(week, { number: new Intl.NumberFormat(locale).format(53) })],
        secondary: Array.from({ length: 7 }, (_, index) => {
          const first = startOfWeek(`${2020 + index}-12-31`, weekStart);
          return formatRange(first, endOf("week", first), locale, to);
        }),
      };
    case "month":
      return { primary: Array.from({ length: 12 }, (_, month) => formatDay(`2026-${pad(month + 1)}-01`, locale, { month: "long", year: "numeric" })), secondary: [] };
    case "year":
      return { primary: [formatDay("2026-01-01", locale, { year: "numeric" })], secondary: [] };
  }
}
